<?php require_once __DIR__.'/includes/functions.php'; $title='Destinations'; include __DIR__.'/includes/header.php'; $slug=$_GET['slug']??''; $stmt=db()->prepare("SELECT d.*,c.name category_name FROM destinations d LEFT JOIN categories c ON c.id=d.category_id WHERE d.status='active' AND (?='' OR d.slug=?) ORDER BY d.name"); $stmt->execute([$slug,$slug]); $rows=$stmt->fetchAll(); ?>
<main class="container py-5"><h1 class="display-serif">Destinations</h1><p class="text-muted">Find your next story.</p><div class="row g-4 mt-2"><?php foreach($rows as $d): ?><div class="col-md-6 col-lg-4"><article class="card h-100"><?php if($d['cover_image']): ?><img class="card-img-top" src="<?=e($d['cover_image'])?>" alt="<?=e($d['name'])?>"><?php endif; ?><div class="card-body"><span class="badge text-bg-success"><?=e($d['category_name']??'Explore')?></span><h2 class="h4 mt-2"><?=e($d['name'])?></h2><p><?=e($d['short_description'])?></p><a href="attractions.php?destination=<?=e((string)$d['id'])?>" class="btn btn-success">See attractions</a></div></article></div><?php endforeach; ?></div></main><?php include __DIR__.'/includes/footer.php'; ?>
